const originals=new WeakMap(),attributes=new WeakMap();
function translateText(s){const stripped=s.trim();if(EN[stripped])return s.replace(stripped,EN[stripped]);let out=s;for(const [ar,en] of [...EN_PHRASES].sort((a,b)=>b[0].length-a[0].length))out=out.split(ar).join(en);for(const [ar,en] of Object.entries(EN).filter(([ar])=>ar.length>=4).sort((a,b)=>b[0].length-a[0].length))out=out.split(ar).join(en);return out;}
function localize(root=document.body){if(!root)return;const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);let n;while(n=walker.nextNode()){if(n.parentElement?.closest('script,style,textarea,.avatar,.print-only'))continue;if(!originals.has(n))originals.set(n,n.nodeValue);const source=originals.get(n);n.nodeValue=uiLang==='en'?translateText(source):source;}root.querySelectorAll('[placeholder],[title],[aria-label]').forEach(el=>{if(!attributes.has(el))attributes.set(el,Object.fromEntries(['placeholder','title','aria-label'].filter(a=>el.hasAttribute(a)).map(a=>[a,el.getAttribute(a)])));for(const [key,value]of Object.entries(attributes.get(el)))el.setAttribute(key,uiLang==='en'?translateText(value):value);});}
function applyLanguage(){document.documentElement.lang=uiLang;document.documentElement.dir=uiLang==='ar'?'rtl':'ltr';document.getElementById('languageButton').textContent=uiLang==='ar'?'English':'العربية';localize();}
new MutationObserver(records=>{if(records.some(r=>r.type==='childList'))localize();}).observe(document.body,{childList:true,subtree:true});
document.getElementById('languageButton').addEventListener('click',()=>{uiLang=uiLang==='ar'?'en':'ar';localStorage.setItem('zarqa-language',uiLang);render();applyLanguage();});
queueMicrotask(applyLanguage);

